<script lang="ts">
  import {onMount,tick,untrack} from 'svelte';
  import {Plus,Trash2,Upload,Clipboard,Download,Eye,Maximize2,AlignLeft,AlignCenter,AlignRight} from '@lucide/svelte';
  import Dialog from './Dialog.svelte';
  import {Button,DialogFooter} from './ui';
  import Notice from './ui/Notice.svelte';
  import SlideCanvas from './SlideCanvas.svelte';
  import TableStyleChoices from './TableStyleChoices.svelte';
  import NumberField from './ui/NumberField.svelte';
  import ColorField from './ui/ColorField.svelte';
  import {changeTableAxis,pasteTableRange,cellOwner} from '../core/table-structure';
  import {tablePresentation,tablePresetStyle} from '../core/table-appearance';
  import type {TableStyle} from '../core/table-schema';
  import {uiDisclosure} from '../ui-motion';
  import {editor} from '../core/editor.svelte';
  import {parseTableData,tableCells,tableCsv} from '../core/object-data';
  import {decodeDataFile} from '../core/delimited-data';
  import {loadLibraryTypography} from '../core/font-loading';
  import {tableRowHeights} from '../core/table-fit';
  import {contentTableColumns} from '../core/table-columns';
  import {download} from '../core/download';
  import {styleOverrides} from '../core/deck-design-system';
  import type {SlideElement} from '../core/model';
  let {elementId,onclose,initialTab='data'}:{elementId:string;onclose:()=>void;initialTab?:'data'|'style'}=$props();
  const gridId=$props.id();
  const base=editor.snapshot(),slideId=editor.slide!.id,slide=base.slides.find(s=>s.id===slideId)!,seed=slide.elements.find(e=>e.id===elementId)!;
  const initial=tableCells(seed.cells?.length?seed.cells:[['']]);
  let height=$state(seed.h),activeDataCell=$state<{row:number;column:number}>();
  function cellLabel(row:number,column:number){return `${String.fromCharCode(65+column)}${row+1}`;}
  function coveredBy(row:number,column:number){const owner=cellOwner(tableStyle,{row,column});return owner.row===row&&owner.column===column?undefined:cellLabel(owner.row,owner.column);}
  let tableStyle=$state<TableStyle|undefined>(seed.tableStyle), selectedColumn=$state(0), colorValidity=$state<Record<string,boolean>>({});
  let cells=$state(initial),fontSize=$state<number|string>(seed.fontSize),fill=$state(seed.fill),stroke=$state(seed.stroke),align=$state(seed.align);
  let tab=$state<'data'|'style'>(untrack(()=>initialTab)),expanded=$state(false),previewOpen=$state(true),pasteOpen=$state(false),paste=$state(''),error=$state(''),status=$state(''),importing=$state(false),fontsReady=$state(false);
  let workspace=$state<HTMLDivElement>(),grid=$state<HTMLDivElement>(),fileInput=$state<HTMLInputElement>(),pasteInput=$state<HTMLTextAreaElement>();
  const columns=$derived(Math.max(1,...cells.map(row=>row.length))),stale=$derived(editor.deck?.id!==base.id||editor.deck?.revision!==base.revision||editor.slide?.id!==slideId);
  const sizeValid=$derived(String(fontSize).trim()!==''&&Number.isFinite(Number(fontSize))&&Number(fontSize)>=4&&Number(fontSize)<=500);
  const patch=$derived({h:height,tableStyle,cells,fontSize:sizeValid?Number(fontSize):seed.fontSize,fill,stroke,align});
  const preview=$derived({...seed,...patch,x:0,y:0,rotation:0,hidden:false,locked:false,group:undefined});
  const previewSlide=$derived({...slide,elements:[preview],groups:[],autoLayouts:[],originalImage:undefined});
  const presentation=$derived(tablePresentation(preview,base.designSystem));
  const changed=$derived(height!==seed.h||JSON.stringify(tableStyle)!==JSON.stringify(seed.tableStyle)||JSON.stringify(cells)!==JSON.stringify(initial)||Number(fontSize)!==seed.fontSize||fill!==seed.fill||stroke!==seed.stroke||align!==seed.align);
  const overflow=$derived(fontsReady&&tableRowHeights(preview).reduce((a,b)=>a+b,0)>preview.h+1);
  const blocked=$derived(stale||importing||!sizeValid||Object.values(colorValidity).some(v=>!v)||seed.locked);
  onMount(()=>{let active=true;void loadLibraryTypography([{...slide,elements:[seed]}],base.fonts).then(()=>document.fonts.ready).finally(()=>{if(active)fontsReady=true;}).catch(()=>{});return()=>{active=false;};});
  async function focus(row:number,column:number,select=true){await tick();const field=grid?.querySelector<HTMLTextAreaElement>(`[data-row="${row}"][data-column="${column}"]`);field?.focus({preventScroll:true});field?.scrollIntoView({block:'nearest',inline:'nearest'});if(select)field?.select();}
  function revealField(event:FocusEvent){
    const field=event.target;
    if(!(field instanceof HTMLTextAreaElement)||!field.dataset.row||!grid)return;
    activeDataCell={row:Number(field.dataset.row),column:Number(field.dataset.column)};
    field.scrollIntoView({block:'nearest',inline:'nearest'});
    const frozen=grid.querySelector('tbody th'),head=grid.querySelector('thead');
    const left=(frozen?.getBoundingClientRect().right??grid.getBoundingClientRect().left)+4,right=(grid.querySelector('tbody td:last-child')?.getBoundingClientRect().left??grid.getBoundingClientRect().right)-4;
    if(field.getBoundingClientRect().right>right)grid.scrollLeft+=field.getBoundingClientRect().right-right;
    if(field.getBoundingClientRect().left<left)grid.scrollLeft-=left-field.getBoundingClientRect().left;
    if(head&&field.getBoundingClientRect().top<head.getBoundingClientRect().bottom+4)grid.scrollTop-=head.getBoundingClientRect().bottom+4-field.getBoundingClientRect().top;
  }
  function edit(row:number,column:number,value:string){const next=cells.map(r=>[...r]);while(next[row].length<columns)next[row].push('');next[row][column]=value;cells=next;error='';}
  function navigate(event:KeyboardEvent,row:number,column:number){
    if(event.isComposing||event.keyCode===229)return;
    if(event.altKey&&event.key==='Enter'){event.preventDefault();const field=event.currentTarget as HTMLTextAreaElement;field.setRangeText('\n',field.selectionStart,field.selectionEnd,'end');edit(row,column,field.value);return;}
    if(event.altKey||event.ctrlKey||event.metaKey)return;
    if(event.key==='Enter'){event.preventDefault();const next=row+(event.shiftKey?-1:1);if(next>=0&&next<cells.length)void focus(next,column);}
    else if(event.key==='Tab'){const next=row*columns+column+(event.shiftKey?-1:1);if(next>=0&&next<cells.length*columns){event.preventDefault();void focus(Math.floor(next/columns),next%columns);}}
  }
  function add(axis:'row'|'column'){try{const index=axis==='row'?cells.length:columns,next=changeTableAxis(preview,axis,index,1,true);cells=next.cells;tableStyle=next.tableStyle;void focus(axis==='row'?index:0,axis==='column'?index:0);error='';}catch(e){error=(e as Error).message;}}
  function remove(axis:'row'|'column',index:number){try{const next=changeTableAxis(preview,axis,index,1,false);cells=next.cells;tableStyle=next.tableStyle;selectedColumn=Math.min(selectedColumn,Math.max(0,columns-1));void focus(axis==='row'?Math.min(index,cells.length-1):0,axis==='column'?Math.min(index,columns-1):0);error='';}catch(e){error=(e as Error).message;}}
  function changeStyle(patch:Partial<TableStyle>){tableStyle={...(tableStyle??{headerRow:true,padding:seed.tableFit?.padding??12,borders:'grid'}),...patch};}
  function columnAlignment(value:string){const columnAlign=Array.from({length:columns},(_,j)=>tableStyle?.columnAlign?.[j]??'auto');columnAlign[selectedColumn]=value as NonNullable<TableStyle['columnAlign']>[number];changeStyle({columnAlign});}
  function columnWidth(value:string|number){const n=Number(value);if(columns<=1||!Number.isFinite(n)||n<1||n>seed.w-(columns-1))return;const other=1-presentation.widths[selectedColumn];const columnWidths=presentation.widths.map((w,j)=>j===selectedColumn?n:(seed.w-n)*w/other);changeStyle({columnWidths});}
  function rangePaste(event:ClipboardEvent,row:number,column:number){const text=event.clipboardData?.getData('text/plain')??'';if(!/[\t\r\n]/.test(text))return;event.preventDefault();try{const result=pasteTableRange(preview,text,{anchor:{row,column},head:{row,column}});cells=result.cells;tableStyle=result.tableStyle;status=`Pasted ${result.rows} × ${result.columns} cells`;error='';}catch(e){error=`${(e as Error).message} Current data is unchanged.`;}}
  function replace(text=paste,source='Replaced data'){try{cells=parseTableData(text);if(tableStyle)tableStyle={...tableStyle,merges:undefined,cellStyles:tableStyle.cellStyles?.filter(s=>s.row<cells.length&&s.column<Math.max(...cells.map(r=>r.length)))};selectedColumn=Math.min(selectedColumn,Math.max(0,columns-1));pasteOpen=false;error='';status=`${source} · ${cells.length} rows · ${columns} columns`;void focus(0,0);}catch(e){error=`${(e as Error).message} Current data is unchanged.`;}}
  async function importFile(file?:File){if(!file)return;importing=true;try{if(file.size>250_000)throw new Error('Use a data file smaller than 250 KB.');replace(decodeDataFile(new Uint8Array(await file.arrayBuffer())),`Imported ${file.name}`);}catch(e){error=`${(e as Error).message} Current data is unchanged.`;}finally{importing=false;if(fileInput)fileInput.value='';}}
  async function togglePaste(){pasteOpen=!pasteOpen;await tick();if(pasteOpen)pasteInput?.focus();else workspace?.querySelector<HTMLButtonElement>('[data-paste-trigger]')?.focus();}
  function showPreview(){expanded=false;previewOpen=true;workspace?.scrollTo({top:0});}
  function apply(){if(blocked||!changed)return;try{const revision=editor.deck!.revision;editor.commit([{op:'update_element',slideId,elementId,patch:{...Object.fromEntries(Object.entries(patch).filter(([key])=>key!=='cells')),...(JSON.stringify(cells)!==JSON.stringify(initial)?{cells:tableCells(cells)}:{}),design:styleOverrides(seed,patch)}}],'','manual',base.revision);if(editor.deck!.revision===revision){error=editor.error;return;}editor.notify('Updated table · ⌘Z to undo');onclose();}catch(e){error=(e as Error).message;}}
</script>
<Dialog title="Edit table" subtitle="Preview locally · Apply when ready" workspace class="table-dialog" {onclose}>
  <div class="table-workspace" class:expanded={expanded&&tab==='data'} bind:this={workspace}>
    <section class="table-preview" aria-label="Table preview">
      <div class="preview-heading"><span>Preview</span><small>{cells.length} {cells.length===1?'row':'rows'} · {columns} {columns===1?'column':'columns'}</small><button class="text-btn preview-toggle" aria-label={previewOpen ? 'Hide preview' : 'Show preview'} aria-expanded={previewOpen} onclick={()=>previewOpen=!previewOpen}>{previewOpen?'Hide':'Show'}</button></div>
      <div class="preview-content" class:hidden-preview={!previewOpen}>
        <div class="preview-stage" style:aspect-ratio={`${seed.w}/${height}`} style:background={slide.background}><SlideCanvas deck={{...base,width:seed.w,height}} slide={previewSlide}/></div>
        <p>{presentation.headerRow?'First row is the header. ':''}Apply to save your changes.</p>
        {#if overflow}<Notice tone="warning" message="The content may exceed the table height." detail="Fit the height, reduce spacing or use fewer rows.">{#snippet actions()}<Button variant="secondary" disabled={height>=base.height-seed.y} onclick={()=>height=Math.min(Math.ceil(tableRowHeights(preview).reduce((a,b)=>a+b,0)),Math.max(1,base.height-seed.y))}>Fit height</Button>{/snippet}</Notice>{/if}
        <Button variant="quiet" disabled={importing} onclick={()=>download(tableCsv(cells),'table-data.csv','text/csv;charset=utf-8')}><Download size={14}/>Data CSV</Button>
      </div>
    </section>
    <section class="table-controls" aria-label="Table settings">
      <fieldset disabled={importing}>
        <div class="table-tabs" role="group" aria-label="Table editor view"><button aria-pressed={tab==='data'} onclick={()=>tab='data'}>Data</button><button aria-pressed={tab==='style'} onclick={()=>tab='style'}>Style</button></div>
        {#if tab==='data'}
          <div class="data-tools"><Button variant="quiet" busy={importing} onclick={()=>fileInput?.click()}><Upload size={14}/>Import CSV</Button><Button variant="quiet" data-paste-trigger aria-expanded={pasteOpen} onclick={togglePaste}><Clipboard size={14}/>Paste data</Button><Button variant="quiet" class="expand-data" aria-label={expanded?'Show preview':'Expand data'} aria-pressed={expanded} onclick={()=>expanded=!expanded}><Maximize2 size={14}/>{expanded?'Show preview':'Expand data'}</Button><input hidden type="file" accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain" bind:this={fileInput} aria-label="Table CSV file" onchange={event=>importFile(event.currentTarget.files?.[0])}/></div>
          {#if pasteOpen}<div class="paste-data"><p>CSV or TSV replaces all cells. Empty cells and quoted line breaks are kept.</p><label class="field-label">Data<textarea bind:this={pasteInput} bind:value={paste} rows="5" aria-label="Paste table data" placeholder={'Item\tDescription\tStatus\nResearch\tCustomer interviews\tComplete'}></textarea></label><div class="data-tools"><Button variant="secondary" disabled={!paste.trim()} onclick={()=>replace()}>Replace data</Button><Button variant="quiet" onclick={togglePaste}>Close paste</Button></div></div>{/if}
          {#if status}<p role="status">{status}</p>{/if}
          {#if error}<Notice tone="error" title="Check table data" message={error}/>{/if}
          {#if activeDataCell}<p class="data-location" role="status"><strong>{cellLabel(activeDataCell.row,activeDataCell.column)}</strong><span>{cells[0]?.[activeDataCell.column]||`Column ${activeDataCell.column+1}`}</span></p>{/if}
          <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
          <div class="table-grid" bind:this={grid} role="region" aria-label="Scrollable table data" tabindex="0" onfocusin={revealField}><table><thead><tr><th scope="col"><span class="sr-only">Row</span></th>{#each Array.from({length:columns},(_,j)=>j) as j}<th scope="col" class:active-axis={activeDataCell?.column===j}><div class="column-heading"><span>{String.fromCharCode(65+j)}</span><button class="icon-btn" data-tone="danger" aria-label={`Remove column ${j+1}`} disabled={columns<=1} onclick={()=>remove('column',j)}><Trash2 size={13}/></button></div></th>{/each}<th><span class="sr-only">Remove row</span></th></tr></thead><tbody>{#each cells as row,i}<tr><th scope="row" class:active-axis={activeDataCell?.row===i}>{i+1}</th>{#each Array.from({length:columns},(_,j)=>j) as j}{@const covered=coveredBy(i,j)}<td class:covered-cell={Boolean(covered)}><textarea rows={Math.min(4,Math.max(1,(row[j]??'').split('\n').length))} class:header-cell={presentation.headerRow&&i===0} aria-label={`Row ${i+1}, column ${j+1}`} data-row={i} data-column={j} aria-describedby={covered?`${gridId}-merge-${i}-${j}`:undefined} value={row[j]??''} maxlength="5000" oninput={event=>edit(i,j,event.currentTarget.value)} onkeydown={event=>navigate(event,i,j)} onpaste={event=>rangePaste(event,i,j)}></textarea>{#if covered}<span id={`${gridId}-merge-${i}-${j}`} class="merged-note">Merged with {covered}<span class="sr-only">. This value is kept for splitting.</span></span>{/if}</td>{/each}<td><button class="icon-btn" data-tone="danger" aria-label={`Remove row ${i+1}`} disabled={cells.length<=1} onclick={()=>remove('row',i)}><Trash2 size={14}/></button></td></tr>{/each}</tbody></table></div>
          <div class="data-tools"><Button variant="quiet" aria-label="Add row" disabled={cells.length>=100} onclick={()=>add('row')}><Plus size={14}/>Row</Button><Button variant="quiet" aria-label="Add column" disabled={columns>=20} onclick={()=>add('column')}><Plus size={14}/>Column</Button></div>
          <p>Enter moves down · Tab moves across · Alt+Enter adds a line break. Paste a spreadsheet range into any cell to update or extend the table.</p>
          <p>Up to 250 KB, 100 rows and 20 columns.</p>
        {:else}
          <TableStyleChoices element={preview} system={base.designSystem} onchoose={style=>tableStyle=style}/>
          <div class="style-basics"><NumberField label="Table text size" prefix="Size" preset="font" unit="px" min={4} max={500} step="any" value={fontSize} invalid={!sizeValid} oninput={raw=>fontSize=raw} onchange={value=>fontSize=value}/><label class="field-label">Lines<select aria-label="Table lines" value={presentation.borders} onchange={event=>changeStyle({borders:event.currentTarget.value as TableStyle['borders']})}><option value="rows">Rows</option><option value="grid">Grid</option><option value="none">None</option></select></label></div>
          {#if !sizeValid}<Notice tone="error" message="Enter a text size from 4 to 500 px."/>{/if}
          <div class="style-toggles"><label><input type="checkbox" checked={presentation.headerRow} onchange={event=>changeStyle({headerRow:event.currentTarget.checked})}/>Header row</label><label><input type="checkbox" checked={presentation.banded} onchange={event=>changeStyle({banded:event.currentTarget.checked})}/>Banded rows</label><label><input type="checkbox" checked={tableStyle?.numericAlign??false} onchange={event=>changeStyle({numericAlign:event.currentTarget.checked})}/>Align numbers right</label></div>
          <div class="density-choices" role="group" aria-label="Cell spacing">{#each [{label:'Compact',value:8},{label:'Comfortable',value:14},{label:'Roomy',value:20}] as density}<button aria-pressed={presentation.padding===density.value} onclick={()=>changeStyle({padding:density.value})}>{density.label}</button>{/each}</div>
          <details class="table-custom" use:uiDisclosure><summary>Colors and alignment</summary><div>
            <div class="style-color-row"><span>Text</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table text color':valid}} label="Table text color" value={fill} opaque allowClear={false} onchange={value=>{fill=value;}}/></div>
            {#if presentation.headerRow}<div class="style-color-row"><span>Header</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table header fill':valid}} label="Table header fill" value={presentation.header} opaque allowClear={false} onchange={value=>changeStyle({headerFill:value})}/></div><div class="style-color-row"><span>Header text</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table header text':valid}} label="Table header text" value={presentation.headerText} opaque allowClear={false} onchange={value=>changeStyle({headerText:value})}/></div>{/if}
            {#if presentation.background!=='transparent'}<div class="style-color-row"><span>Background</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table background':valid}} label="Table background" value={presentation.background} opaque allowClear={false} onchange={value=>changeStyle({bodyFill:value})}/></div>{/if}<label class="transparent-table"><input type="checkbox" checked={presentation.background==='transparent'} onchange={event=>{changeStyle({bodyFill:event.currentTarget.checked?'transparent':undefined});colorValidity={...colorValidity,'Table background':true};}}/>Transparent background</label>
            {#if presentation.banded}<div class="style-color-row"><span>Alternating rows</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table stripe fill':valid}} label="Table stripe fill" value={presentation.stripe} opaque allowClear={false} onchange={value=>changeStyle({stripeFill:value})}/></div>{/if}
            <div class="style-color-row"><span>Lines</span><ColorField onvaliditychange={valid=>colorValidity={...colorValidity,'Table border color':valid}} label="Table border color" value={presentation.line} opaque allowClear={false} onchange={value=>{stroke=value;changeStyle({lineColor:value});}}/></div>
            <div class="align-choices" role="group" aria-label="Table text alignment">{#each [{id:'left',label:'Left',icon:AlignLeft},{id:'center',label:'Center',icon:AlignCenter},{id:'right',label:'Right',icon:AlignRight}] as option}<button aria-label={`Align ${option.label.toLowerCase()}`} aria-pressed={align===option.id} onclick={()=>{align=option.id as SlideElement['align'];changeStyle({numericAlign:false,columnAlign:undefined});}}><option.icon size={16}/>{option.label}</button>{/each}</div>
            <div class="style-basics"><NumberField label="Table cell padding" preset="spacing" prefix="Padding" unit="px" min={0} max={48} step="any" value={presentation.padding} onvaliditychange={valid=>colorValidity={...colorValidity,padding:valid}} onchange={padding=>changeStyle({padding})}/><NumberField label="Table line width" preset="stroke" prefix="Lines" unit="px" min={0} max={8} step="any" value={presentation.borderWidth} onvaliditychange={valid=>colorValidity={...colorValidity,borderWidth:valid}} onchange={borderWidth=>changeStyle({borderWidth})}/></div>
            <Button variant="quiet" onclick={()=>{if(tableStyle)tableStyle={...tableStyle,headerFill:undefined,headerText:undefined,bodyFill:undefined,stripeFill:undefined,lineColor:undefined};stroke=seed.stroke;fill=seed.fill;}}>Reset colors</Button>
          </div></details>
          <details class="table-custom" use:uiDisclosure><summary>Column layout</summary><div><label class="field-label">Column<select aria-label="Table column" value={Math.min(selectedColumn,columns-1)} onchange={event=>selectedColumn=Number(event.currentTarget.value)}>{#each Array.from({length:columns},(_,j)=>j) as j}<option value={j}>{String.fromCharCode(65+j)} · {cells[0]?.[j]||`Column ${j+1}`}</option>{/each}</select></label><div class="style-basics"><label class="field-label">Alignment<select aria-label="Column alignment" value={tableStyle?.columnAlign?.[selectedColumn]??'auto'} onchange={event=>columnAlignment(event.currentTarget.value)}><option value="auto">Auto</option><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label><NumberField label="Column width" preset="dimension" presets={[.25,1/3,.5,2/3,.75].map(fraction=>({value:Math.round(seed.w*fraction),label:`${Math.round(fraction*100)}% of table`}))} prefix="Width" unit="px" min={1} max={seed.w-(columns-1)} step="any" disabled={columns<=1} value={Math.round(presentation.widths[selectedColumn]*seed.w)} onvaliditychange={valid=>colorValidity={...colorValidity,columnWidth:valid}} onchange={columnWidth}/></div><div class="data-tools"><Button variant="quiet" busy={!fontsReady} onclick={()=>{changeStyle({columnWidths:contentTableColumns(preview)});colorValidity={...colorValidity,columnWidth:true};}}>Fit columns</Button><Button variant="quiet" onclick={()=>{changeStyle({columnWidths:undefined});colorValidity={...colorValidity,columnWidth:true};}}>Equal widths</Button></div></div></details>
          <p>Presets keep your data, font, text size and column widths. Custom colors stay local to this table.</p>
        {/if}
      </fieldset>
    </section>
  </div>
  {#snippet footer()}<DialogFooter>{#snippet info()}{#if stale}<Notice tone="warning" message="The document changed. Close and reopen this table."/>{:else if Object.values(colorValidity).some(v=>!v)||!sizeValid}<span class="style-error">Check style fields.</span><button class="text-btn" onclick={()=>tab='style'}>Fix style</button>{:else}<span role="status">{!changed?'No changes to apply.':'Apply to save · Undo is available'}</span>{/if}{/snippet}{#snippet actions()}<Button variant="quiet" class={`preview-action ${expanded ? 'data-preview-action' : ''}`} aria-label="Preview" onclick={showPreview}><Eye size={14}/><span>Preview</span></Button><Button variant="secondary" onclick={onclose}>Cancel</Button><Button variant="primary" aria-label="Apply changes" disabled={blocked||!changed} onclick={apply}>Apply</Button>{/snippet}</DialogFooter>{/snippet}
</Dialog>
<style>
  .style-error{color:var(--danger-text)}
